{
  "name": "@relf108/opencode-watchdog",
  "version": "2.0.1",
  "description": "opencode plugin: scope enforcement, test-baseline commit gate, drift tracking, and an LLM danger-gate backed by a visible watchdog-auditor agent.",
  "type": "module",
  "main": "plugin.js",
  "exports": {
    ".": "./plugin.js",
    "./engine": "./engine.mjs",
    "./shell": "./shell.mjs"
  },
  "bin": {
    "watchdog": "cli.mjs"
  },
  "files": [
    "plugin.js",
    "engine.mjs",
    "shell.mjs",
    "cli.mjs",
    "instructions.md",
    "CHANGELOG.md"
  ],
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "watchdog",
    "guardrails"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.1.1"
  }
}
